export class SextantApiError extends Error {
  readonly code: string
  readonly status: number
  readonly details: Record<string, unknown>

  constructor(status: number, payload: unknown) {
    const normalized = normalizeApiError(status, payload)
    super(normalized.error.message)
    this.name = "SextantApiError"
    this.status = status
    this.code = normalized.error.code
    this.details = normalized.error.details
  }
}

function normalizeApiError(status: number, payload: unknown): ApiError {
  if (
    payload
    && typeof payload === "object"
    && "error" in payload
    && typeof (payload as ApiError).error?.message === "string"
  ) {
    return payload as ApiError
  }
  return {
    error: {
      code: `http_${status}`,
      message: readableErrorPayload(payload) || `Request failed with status ${status}.`,
      details:
        payload && typeof payload === "object"
          ? { payload: payload as Record<string, unknown> }
          : {},
    },
  }
}

function readableErrorPayload(payload: unknown): string | null {
  if (payload && typeof payload === "object" && "detail" in payload) {
    const detail = (payload as { detail?: unknown }).detail
    if (typeof detail === "string") return detail
    if (Array.isArray(detail) && detail.length > 0) return "请求参数校验失败。"
  }
  return null
}

