  private headers(headers: WriteHeaders) {
    const output: Record<string, string> = {
      "Content-Type": "application/json",
      "X-Actor-Id": headers.actorId,
      "X-Request-Id": headers.requestId,
      "Idempotency-Key": headers.idempotencyKey,
    }
    if (headers.bearerToken) output.Authorization = `Bearer ${headers.bearerToken}`
    return output
  }

  private readHeaders(headers: ReadHeaders) {
    const output: Record<string, string> = {
      "X-Actor-Id": headers.actorId,
    }
    if (headers.bearerToken) output.Authorization = `Bearer ${headers.bearerToken}`
    return output
  }

  private async request<T>(path: string, init: RequestInit): Promise<T> {
    const response = await fetch(`${this.baseUrl}${path}`, init)
    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new SextantApiError(response.status, payload)
    }
    return payload as T
  }
